create type public.app_role as enum ('viewer', 'editor', 'reviewer', 'admin');
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 1 and 120), created_at timestamptz not null default now());
create table public.memberships (organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.app_role not null default 'viewer', created_at timestamptz not null default now(), primary key (organization_id, user_id));
create table public.model_cards (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, created_by uuid not null references auth.users(id), payload jsonb not null, readiness_score numeric(5,2) not null check (readiness_score between 0 and 100), created_at timestamptz not null default now(), expires_at timestamptz not null default now() + interval '365 days');
create table public.evidence_items (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, model_card_id uuid references public.model_cards(id) on delete cascade, created_by uuid not null references auth.users(id), kind text not null, payload jsonb not null, created_at timestamptz not null default now(), expires_at timestamptz not null default now() + interval '365 days');
create table public.audit_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, actor_id uuid not null references auth.users(id), event_type text not null, payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), expires_at timestamptz not null default now() + interval '7 years');
alter table public.organizations enable row level security; alter table public.memberships enable row level security; alter table public.model_cards enable row level security; alter table public.evidence_items enable row level security; alter table public.audit_events enable row level security;
create function public.is_member(target_org uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.memberships where organization_id = target_org and user_id = auth.uid()) $$;
create function public.has_role(target_org uuid, allowed public.app_role[]) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.memberships where organization_id = target_org and user_id = auth.uid() and role = any(allowed)) $$;
create policy "members read organizations" on public.organizations for select to authenticated using (public.is_member(id));
create policy "members read memberships" on public.memberships for select to authenticated using (public.is_member(organization_id));
create policy "members read cards" on public.model_cards for select to authenticated using (public.is_member(organization_id));
create policy "editors create cards" on public.model_cards for insert to authenticated with check (public.is_member(organization_id) and created_by = auth.uid());
create policy "members read evidence" on public.evidence_items for select to authenticated using (public.is_member(organization_id));
create policy "editors create evidence" on public.evidence_items for insert to authenticated with check (public.has_role(organization_id, array['editor','reviewer','admin']::public.app_role[]) and created_by = auth.uid());
create policy "members read audit" on public.audit_events for select to authenticated using (public.is_member(organization_id));
create policy "reviewers create audit" on public.audit_events for insert to authenticated with check (public.has_role(organization_id, array['reviewer','admin']::public.app_role[]) and actor_id = auth.uid());
revoke all on public.organizations, public.memberships, public.model_cards, public.evidence_items, public.audit_events from anon;
grant select on public.organizations, public.memberships, public.model_cards, public.evidence_items, public.audit_events to authenticated;
grant insert on public.model_cards, public.evidence_items, public.audit_events to authenticated;
